local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule

---@class UITalentMaterialPurchaseDialog
local UITalentMaterialPurchaseDialog = Class("UITalentMaterialPurchaseDialog")

function UITalentMaterialPurchaseDialog:__init() 
end

function UITalentMaterialPurchaseDialog:__delete()
end

function UITalentMaterialPurchaseDialog:Awake()
    self._everythingChangeHandler = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.OnEveryThingChangeEventName))
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.ButtonItem, Bind(self, self.OnBtnBuy))

    self:FillTicketInfo()
    self:StartTimeDown()
end

--门票信息
function UITalentMaterialPurchaseDialog:FillTicketInfo()
    local ticketId = QuestConfMgr:GetInstance():GetTalentTicketId()
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(ticketId)
    CfUtils.FillImage(self.GoodIcon, path)
    self:FillTicketCount()

    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(ticketId)
    if vo then
        CfUtils.FillText(self.TxtName, vo.name)
        local maxTime = QuestConfMgr:GetInstance():GetTalentTicketMaxBuy()
        local buyTime = talentQuestComponent:GetBuyTicketsTimes()
        CfUtils.FillText(self.TxtDesc, (maxTime - buyTime).."/"..maxTime)
        CfUtils.FillText(self.Desc, vo.desc)
    end

    local consumeId = QuestConfMgr:GetInstance():GetTalentTicketConsumeId()
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(consumeId)
    CfUtils.FillImage(self.ConsumeIcon, path)
    local consumeNum = QuestConfMgr:GetInstance():GetTalentTicketConsumeNum()
    CfUtils.FillText(self.TxtConsumeNumber, consumeNum)
end

function UITalentMaterialPurchaseDialog:FillTicketCount()
    local maxNum = QuestConfMgr:GetInstance():GetTalentMaxTicketHave()
    local haveNum = talentQuestComponent:GetCurTicketCount()
    CfUtils.FillText(self.TxtNum, haveNum.."/"..maxNum)
    local time = talentQuestComponent:GetTicketsRecoverTime()
    if time > 0 then
        CfUtils.FillText(self.TxtNumber, CfUtils.GetTimeHMS2(time))
    else
        CfUtils.FillText(self.TxtNumber, localize("已上限"))
    end
end

function UITalentMaterialPurchaseDialog:StartTimeDown()
    self:ClearTimeDown()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local time = talentQuestComponent:GetTicketsRecoverTime()
        if time > 0 then
            CfUtils.FillText(self.TxtNumber, CfUtils.GetTimeHMS2(time))
        else
            CfUtils.FillText(self.TxtNumber, localize("已上限"))
        end
    end, CountDownTime, false, true)
end

function UITalentMaterialPurchaseDialog:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function UITalentMaterialPurchaseDialog:OnBtnClose()
    UIModule.CloseDialog(self.controller)
end

function UITalentMaterialPurchaseDialog:OnBtnBuy()
    self:OnBtnClose()
    talentQuestComponent:BuyTicketsReq()
end

function UITalentMaterialPurchaseDialog:OnEveryThingChangeEventName(body)
    self:FillTicketCount()
end

function UITalentMaterialPurchaseDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end))
    return coWait
end

function UITalentMaterialPurchaseDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:ClearTimeDown()
        Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self._everythingChangeHandler)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UITalentMaterialPurchaseDialog
